(function(root,factory){const value=factory();if(typeof module==='object'&&module.exports)module.exports=value;else root.obTranslateModel=value})(this,function(){'use strict';
function eligible(value){try{const u=new URL(value);if(!['http:','https:'].includes(u.protocol)||u.username||u.password)return false;const h=u.hostname.toLowerCase();return h!=='localhost'&&!h.endsWith('.localhost')&&!h.endsWith('.local')&&!h.endsWith('.internal')&&h.includes('.')&&!/^\d+\.\d+\.\d+\.\d+$/.test(h)&&!h.includes(':')}catch(e){return false}}
function normalize(raw){if(!raw||typeof raw.documentId!=='string'||!raw.documentId||raw.documentId.length>128)throw new Error('No active document');const url=String(raw.url||'');return {documentId:raw.documentId,title:String(raw.title||'Current page').slice(0,200),url,origin:eligible(url)?new URL(url).origin:'This page cannot be translated',language:String(raw.language||'Unknown').slice(0,40),translated:raw.translated===true,canGoBack:raw.canGoBack===true,eligible:eligible(url)}}
function command(context,restore){const c=normalize(context);if(restore){if(!c.translated||!c.canGoBack)throw new Error('Original page is unavailable')}else if(!c.eligible||c.translated)throw new Error('Page cannot be translated');return {documentId:c.documentId,action:restore?'restore':'translate',target:'en'}}
return {eligible,normalize,command}});
